/**
 * Vendored verbatim from motion-primitives (https://motion-primitives.com) by ibelick.
 * Upstream: https://github.com/ibelick/motion-primitives/blob/main/components/core/in-view.tsx
 * Fetched 2026-08-29 from main branch. Do not edit unless intentionally adopting upstream changes.
 */
'use client';
// Local patch for workspace tsconfig (verbatimModuleSyntax): type-only imports only, no behavior change.
import { useRef, useState, type ReactNode } from 'react';
import { motion, useInView, type Variant, type Transition, type UseInViewOptions,  } from 'motion/react';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean;
  delay?: number;
  className?: string;
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

export function InView({
  children,
  variants = defaultVariants,
  transition,
  delay,
  viewOptions,
  as = 'div',
  once
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false)

  const MotionComponent = motion[as as keyof typeof motion] as typeof as;

  return (
    <MotionComponent
      ref={ref}
      initial='hidden'
      onAnimationComplete={() => {
        if (once) setIsViewed(true)
      }}
      animate={(isInView || isViewed) ? "visible" : "hidden"}

      variants={variants}
      transition={delay !== undefined ? { ...transition, delay } : transition}
    >
      {children}
    </MotionComponent>
  );
}

/**
 * scroll-pinned-chapters — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/scroll-pinned-chapters.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { motion, useScroll, useTransform } from "motion/react"

import { cn } from "@/lib/utils"

// ═══ JOB         Pinned chapters — a sticky stage where chapters crossfade as you scroll.
// ═══ EMOTION     Storytelling that stays in one place.
// ═══ SIGNATURE   A pinned viewport that steps through chapters (title/content) on scroll.

export type Chapter = { id: string; title: string; body?: string; progress?: number }

export type ScrollPinnedChaptersProps = {
  eyebrow?: string
  chapters: Chapter[]
  tone?: "paper" | "ink"
  className?: string
}

const DEFAULT_CHAPTERS = [
  { id: "ch1", title: "Listen", body: "An hour in the workshop before any drawing exists.", progress: 0.25 },
  { id: "ch2", title: "Draw", body: "Full-scale, taped on the floor, argued over twice.", progress: 0.5 },
  { id: "ch3", title: "Build", body: "One maker, one piece, photos every Friday.", progress: 0.75 },
  { id: "ch4", title: "Hand over", body: "Placed, levelled, cared for — in writing.", progress: 1 },
]
export function ScrollPinnedChapters({ eyebrow = "CHAPTERS", chapters = DEFAULT_CHAPTERS, tone = "paper", className }: ScrollPinnedChaptersProps) {
  const ink = tone === "ink"
  const ref = React.useRef<HTMLDivElement>(null)
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start start", "end end"] })
  const runway = `${chapters.length * 100 + 40}vh`
  const [idx, setIdx] = React.useState(0)
  React.useEffect(() => {
    return scrollYProgress.on("change", (v) => {
      setIdx(Math.min(chapters.length - 1, Math.floor(v * chapters.length)))
    })
  }, [scrollYProgress, chapters.length])
  const scale = useTransform(scrollYProgress, [0, 1], [0.94, 1.04])

  return (
    <section ref={ref} className={cn("relative isolate w-full bg-background", className)} style={{ height: runway }}>
      <div className="sticky top-0 flex h-screen items-center justify-center overflow-hidden">
        <motion.div style={{ scale }} className="mx-auto max-w-2xl px-5 text-center sm:px-8">
          <span className={cn("inline-flex items-center gap-2 font-mono text-[11px] font-bold uppercase tracking-[0.18em]", cn(ink ? "text-background/55" : "text-muted-foreground", "justify-center"))}><span aria-hidden className="inline-block size-[5px] rotate-45 bg-current" />{eyebrow}</span>
          <div className="relative mt-6 min-h-[220px]">
            {chapters.map((c, i) => (
              <motion.div
                key={c.id}
                initial={false}
                animate={{ opacity: i === idx ? 1 : 0, y: i === idx ? 0 : 24 }}
                transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                className={cn("absolute inset-0", i !== idx && "pointer-events-none")}
              >
                <h2 className="font-display text-4xl font-bold tracking-[-0.03em] sm:text-6xl">{c.title}</h2>
                {c.body && <p className={cn("mx-auto mt-4 max-w-md text-base font-medium leading-relaxed", ink ? "text-background/70" : "text-muted-foreground")}>{c.body}</p>}
                <p className="mt-6 font-mono text-[10px] font-bold uppercase tracking-widest text-muted-foreground">CHAPTER {i + 1} / {chapters.length}</p>
              </motion.div>
            ))}
          </div>
          {/* progress dots */}
          <div className="mt-8 flex justify-center gap-2">
            {chapters.map((c, i) => (
              <span key={c.id} className={cn("h-1 w-8 rounded-full transition-colors", i === idx ? "bg-foreground" : "bg-muted")} />
            ))}
          </div>
        </motion.div>
      </div>
    </section>
  )
}

